random, err := rand.Int(rand.Reader, big.NewInt(100))
if err != nil {
	log.Fatal(err)
}

tmpl, err := template.New("greeting").Parse("Hello World {{.}}\n")
if err != nil {
	log.Fatal(err)
}
if err := tmpl.Execute(os.Stdout, random); err != nil {
	log.Fatal(err)
}

